      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "U3: Enable Windows Native Build",
      "activity_description": "Fix Gradle build scripts, path generation logic, line endings, and batch wrappers to allow full compilation and testing on a local Windows machine.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "U4: Windows EC2 Provisioning and CI Acceptance Testing",
      "activity_description": "Provision a Windows EC2 instance, configure CI build agent, run acceptance tests, fix Windows-specific test execution issues, and integrate build steps into CI.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "U5: Spark Streaming Data Processors (Java & Scala)",
      "activity_description": "Design and implement Spark Streaming processors for Spring XD using Java 8 Lambdas and Scala, including build configurations and unit/integration tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "U6: Reference Guide Copyright Update",
      "activity_description": "Update copyright year metadata to 2015 in the documentation source files and verify PDF generation output.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "U7: Backport Kafka Changes and Upgrade to SI Kafka GA",
      "activity_description": "Backport Spring XD custom Kafka features to Spring Integration Kafka, bump SI Kafka dependency to GA, and resolve resulting compilation and integration test issues.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "U8: Upgrade to SHDP GA Release",
      "activity_description": "Upgrade Spring for Apache Hadoop (SHDP) dependencies to GA release, adjust API usage across Hadoop modules, and verify compatibility with existing tests.",
